<script setup lang="ts">
import { ref,reactive,computed,watch,onBeforeUnmount } from 'vue';
import { request } from '../crm-api';
interface Message {id:string;kind:string;direction:string;sender:string;recipient:string;subject:string;body:string;status:string;created_at:string;quote_id:number|null;version:number|null;analysis:{state:string;summary?:string;facts?:{field:string;value:string;evidence:string}[]}}
interface Task {id:string;title:string;due_at:string|null;status:string}
interface Workspace {communications:Message[];legacy:{id:number;note:string;created_at:string;next_at:string}[];tasks:Task[];ai:{configured:boolean;model:string}}
const props=defineProps<{inquiry:{id:number;company:string;contact_name:string;channel:string;locale?:string};locale:string;quote?:{quote_id:number;version:number;locale:string;currency:string;total:string}}>();
const emit=defineEmits<{changed:[]}>();
const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const workspace=ref<Workspace>({communications:[],legacy:[],tasks:[],ai:{configured:false,model:'gpt-5'}});
const config=ref({configured:false,sender:''}),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),compose=ref(false),noteOpen=ref(false),expanded=ref<string[]>([]);
const note=reactive({kind:'phone',body:''});
const form=reactive({recipient:'',subject:'',body:'',send_key:crypto.randomUUID(),locale:'zh',goal:''});
const cacheKey=computed(()=>`vera-email-${props.inquiry.id}-${props.quote?.quote_id||'inquiry'}-${props.quote?.version||0}`);
const summaries=computed(()=>workspace.value.communications.filter(m=>m.analysis.state==='ready').slice(0,3));
const pendingTasks=computed(()=>workspace.value.tasks.filter(t=>t.status!=='done'));
const unknownSend=ref(false);
function when(value:string){return new Intl.DateTimeFormat(props.locale==='zh'?'zh-CN':'en-NZ',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
function kind(m:Message){return m.kind==='email'?(m.direction==='inbound'?tx('客户来信','CUSTOMER EMAIL'):tx('发出邮件','OUTBOUND EMAIL')):({phone:tx('电话记录','PHONE'),wechat:tx('微信记录','WECHAT'),note:tx('内部备注','INTERNAL NOTE')} as Record<string,string>)[m.kind]}
function status(value:string){return ({smtp_accepted:tx('邮件服务器已接收','Accepted by mail server'),received:tx('已收取','Received'),sending:tx('正在发送','Sending'),unknown:tx('发送结果待核查','Delivery uncertain'),recorded:tx('已归档','Recorded')} as Record<string,string>)[value]||value}
async function load(){loading.value=true;try{workspace.value=await request(`inquiries/${props.inquiry.id}/workspace`);config.value=await request('email/config')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
function initialize(){compose.value=false;noteOpen.value=false;unknownSend.value=false;error.value='';notice.value='';form.recipient=props.inquiry.channel.match(/[^\s/<>]+@[^\s/<>]+\.[^\s/<>]+/)?.[0]||'';form.locale=props.quote?.locale||props.inquiry.locale||props.locale;form.subject=props.quote?`VERA / Q-${props.quote.quote_id} v${props.quote.version}`:tx(`VERA · ${props.inquiry.company} 项目询价`,`VERA · ${props.inquiry.company} inquiry`);form.goal=props.quote?tx('向客户说明并发送这份正式报价。','Present and send this finalized quotation.'):tx('向客户确认尚缺的规格与项目需求。','Confirm the missing specifications and project requirements.');form.body='';form.send_key=crypto.randomUUID();try{const saved=JSON.parse(sessionStorage.getItem(cacheKey.value)||'null');if(saved)Object.assign(form,saved)}catch{};void load()}
watch(()=>[props.inquiry.id,props.quote?.quote_id,props.quote?.version],initialize,{immediate:true});
watch(form,()=>sessionStorage.setItem(cacheKey.value,JSON.stringify(form)),{deep:true});
let refresh:ReturnType<typeof setInterval>|undefined=setInterval(()=>{if(!document.hidden&&!busy.value)void load()},30000);
onBeforeUnmount(()=>clearInterval(refresh));
async function generate(){busy.value=true;error.value='';try{const result=await request<{subject:string;body:string}>(`inquiries/${props.inquiry.id}/communications/draft-email`,{goal:form.goal,locale:form.locale,quote_id:props.quote?.quote_id||null,version:props.quote?.version||null});form.subject=result.subject;form.body=result.body}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function send(){busy.value=true;error.value='';try{const result=await request<Message>(`inquiries/${props.inquiry.id}/communications/email`,{recipient:form.recipient,subject:form.subject,body:form.body,send_key:form.send_key,quote_id:props.quote?.quote_id||null,version:props.quote?.version||null});if(result.status==='smtp_accepted'){compose.value=false;sessionStorage.removeItem(cacheKey.value);form.body='';form.send_key=crypto.randomUUID();notice.value=tx('邮件已提交给邮件服务器，原文已自动归档。','Mail accepted by the sending server and automatically archived.')}else{unknownSend.value=true;error.value=tx('发送结果未确认。请先检查发件邮箱，避免重复发送。','Delivery could not be confirmed. Check the sending mailbox before retrying.')}await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function recordNote(){busy.value=true;error.value='';try{await request(`inquiries/${props.inquiry.id}/communications/note`,note);note.body='';noteOpen.value=false;await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function done(id:string){try{await request(`project-tasks/${id}/complete`,{});await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function toggle(id:string){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
</script>
<template>
 <section class="project-activity">
  <header class="activity-heading"><div><span class="eyebrow">{{tx('项目沟通','PROJECT COMMUNICATION')}}</span><h3>{{tx('沟通与下一步','Conversation & next steps')}}</h3></div><button class="primary-button" type="button" @click="compose=!compose">{{quote?tx('发送这份报价','Send this quotation'):tx('联系客户','Contact customer')}} ↗</button></header>
  <p v-if="notice" class="activity-notice" role="status">{{notice}}</p><p v-if="error" class="activity-error" role="alert">{{error}}</p>
  <section v-if="compose" class="mail-composer"><header><h4>{{quote?tx('发送报价','Quotation email'):tx('邮件回复','Email reply')}}</h4><button type="button" class="quiet-button" @click="compose=false">{{tx('收起','Close')}}</button></header><p v-if="!config.configured" class="configuration-note">{{tx('邮件服务尚未配置。正文可先编辑，配置完成后即可发送。','Sending service is not configured. You can prepare the message first.')}}</p><form @submit.prevent="send"><div class="mail-meta"><label>{{tx('收件人','To')}}<input v-model="form.recipient" type="email" required :disabled="busy"/></label><label>{{tx('邮件语言','Email language')}}<select v-model="form.locale" :disabled="busy"><option value="zh">中文</option><option value="en">English</option></select></label></div><label>{{tx('主题','Subject')}}<input v-model="form.subject" required maxlength="200" :disabled="busy"/></label><div class="ai-toolbar"><label>{{tx('沟通目的','Purpose')}}<input v-model="form.goal" :disabled="busy" /></label><button type="button" class="ai-button" :disabled="busy||!workspace.ai.configured" :title="workspace.ai.configured?'GPT-5':tx('管理员配置模型后启用','Configure the model to enable')" @click="generate">✦ {{busy?tx('处理中…','Working…'):tx('AI生成正文','AI draft')}}</button></div><label>{{tx('正文','Message')}}<textarea v-model="form.body" required maxlength="10000" :disabled="busy" :placeholder="tx('输入内容，或使用AI根据当前项目生成正文。','Write a message, or generate one from the project context.')"/></label><p v-if="quote" class="attachment-label">{{tx('随邮件附上正式报价文件','Final quotation attached')}} · Q-{{quote.quote_id}} / v{{quote.version}}</p><footer><span>{{tx('发送后自动归档，无需再填写沟通记录。','Automatically archived after sending. No duplicate notes needed.')}}</span><button class="primary-button" :disabled="busy||!config.configured||unknownSend">{{tx('发送邮件','Send email')}} →</button></footer></form></section>
  <div class="activity-overview"><section class="automatic-summary"><div class="small-heading"><h4>{{tx('自动摘要','AUTOMATIC SUMMARY')}}</h4><span>{{workspace.ai.configured?workspace.ai.model:tx('待接入AI','AI not connected')}}</span></div><template v-if="summaries.length"><article v-for="message in summaries" :key="message.id"><p>{{message.analysis.summary}}</p><div v-if="message.analysis.facts?.length" class="extracted-facts"><span v-for="(fact,index) in message.analysis.facts" :key="index" :title="fact.evidence">{{fact.value}}</span></div><button class="source-link" type="button" @click="toggle(message.id)" :aria-expanded="expanded.includes(message.id)">{{tx('查看原文','View source')}} · {{when(message.created_at)}} ↗</button></article></template><p v-else class="empty-copy">{{workspace.ai.configured?tx('新邮件归档后会自动生成摘要、需求变化和下一步。','New archived messages automatically produce summaries and next steps.'):tx('邮件原文会自动归档。接入GPT-5后，摘要与跟进事项也会自动生成。','Messages are automatically archived. Connect GPT-5 to generate summaries and follow-ups.')}}</p></section><section class="next-actions"><div class="small-heading"><h4>{{tx('待跟进','NEXT ACTIONS')}}</h4><span>{{pendingTasks.length}}</span></div><ul v-if="pendingTasks.length"><li v-for="task in pendingTasks" :key="task.id"><button type="button" class="task-check" :aria-label="tx('标记已完成','Mark completed')" @click="done(task.id)">✓</button><div><strong>{{task.title}}</strong><small>{{task.due_at?when(task.due_at):tx('未指定日期','No date specified')}}</small></div></li></ul><p v-else class="empty-copy">{{tx('暂无待办。明确的邮件跟进事项会自动进入这里。','No pending actions. Explicit email follow-ups appear here automatically.')}}</p></section></div>
  <section class="activity-stream"><header><h4>{{tx('沟通时间线','COMMUNICATION TIMELINE')}}</h4><button type="button" class="quiet-button" @click="noteOpen=!noteOpen">+ {{tx('补充电话 / 线下记录','Record a call / offline note')}}</button></header><form v-if="noteOpen" class="offline-note" @submit.prevent="recordNote"><select v-model="note.kind"><option value="phone">{{tx('电话','Phone')}}</option><option value="wechat">{{tx('微信','WeChat')}}</option><option value="note">{{tx('内部备注','Internal note')}}</option></select><textarea v-model="note.body" required :placeholder="tx('只补充系统无法取得原文的沟通。摘要会自动整理。','Only record communications unavailable to the system. Summaries are generated automatically.')"/><button class="secondary-button" :disabled="busy">{{tx('保存原始记录','Save original note')}}</button></form>
   <p v-if="!workspace.communications.length&&!workspace.legacy.length&&!loading" class="empty-copy">{{tx('邮件收发后自动出现在这里。','Sent and received messages appear here automatically.')}}</p>
   <article v-for="message in workspace.communications" :key="message.id" class="message-event" :class="message.direction"><div class="event-dot" aria-hidden="true"/><div class="event-content"><div class="event-meta"><strong>{{kind(message)}}</strong><span>{{when(message.created_at)}}</span><small :class="{uncertain:message.status==='unknown'}">{{status(message.status)}}</small></div><h5 v-if="message.subject">{{message.subject}}</h5><p class="event-address">{{message.sender}}<template v-if="message.recipient"> → {{message.recipient}}</template><span v-if="message.quote_id"> · Q-{{message.quote_id}} / v{{message.version}}</span></p><p v-if="message.analysis.summary" class="event-summary">{{message.analysis.summary}}</p><p v-else class="event-preview">{{message.body.slice(0,180)}}{{message.body.length>180?'…':''}}</p><button type="button" class="source-link" :aria-expanded="expanded.includes(message.id)" @click="toggle(message.id)">{{expanded.includes(message.id)?tx('收起原文','Hide original'):tx('查看原文','Read original')}} ↗</button><pre v-if="expanded.includes(message.id)" class="message-original">{{message.body}}</pre></div></article>
   <details v-if="workspace.legacy.length" class="legacy-records"><summary>{{tx('历史记录','Earlier records')}} · {{workspace.legacy.length}}</summary><article v-for="item in workspace.legacy" :key="item.id"><small>{{when(item.created_at)}}</small><pre>{{item.note}}</pre></article></details>
  </section>
 </section>
</template>
<style scoped>
.project-activity{margin-top:30px;border-top:1px solid #e1e7e2;padding-top:26px;color:#1c2922}.activity-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:.13em;color:#8a988d}.activity-heading h3{font-size:20px;font-weight:600;margin:8px 0 0}.project-activity button{font:500 12px var(--font-body);cursor:pointer;border-radius:5px}.primary-button{border:1px solid #0f6e5c;background:#0f6e5c;color:#fff;padding:11px 16px;min-height:42px}.secondary-button{border:1px solid #d8e1d9;background:#fff;color:#53675b;padding:10px 14px;min-height:40px}.quiet-button{border:0;padding:7px 0;background:transparent;color:#6c7d71;min-height:34px}.activity-overview{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(220px,1fr);gap:24px;margin:0 0 32px}.automatic-summary{background:#f4f7f2;border:1px solid #e5ebe2;border-radius:6px;padding:22px}.small-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px}.small-heading h4,.activity-stream>header h4{font-size:11px;letter-spacing:.08em;font-weight:600;margin:0}.small-heading>span{font-size:10px;color:#859480}.automatic-summary article+article{border-top:1px solid #e0e8dc;padding-top:14px;margin-top:14px}.automatic-summary p{font-size:13px;line-height:1.9;margin:0 0 10px}.extracted-facts{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.extracted-facts span{font-size:10px;padding:3px 7px;background:#e6eee1;color:#4c674b;border-radius:3px}.source-link{display:inline-block;background:transparent;border:0;padding:0;color:#718574;font-size:10px!important;min-height:26px;cursor:pointer}.next-actions{padding:22px 0}.next-actions ul{list-style:none;margin:0;padding:0}.next-actions li{display:flex;gap:10px;align-items:start;padding:12px 0;border-top:1px solid #e9eee9}.next-actions li:first-child{border-top:0}.task-check{display:grid;place-items:center;flex:none;width:24px;height:24px;min-height:0;padding:0;border:1px solid #d3dfd4;background:#fff;color:#adc3ac}.task-check:hover{border-color:#0f6e5c;color:#0f6e5c}.next-actions strong{font-size:12px;font-weight:500;line-height:1.6}.next-actions small{display:block;font-size:10px;color:#89968a;margin-top:4px}.empty-copy{font-size:12px!important;color:#869285;line-height:1.9;margin:0}.activity-stream>header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:22px}.message-event{position:relative;display:flex;gap:18px;padding:0 0 26px}.message-event:not(:last-of-type)::before{content:'';position:absolute;left:4px;top:14px;bottom:0;width:1px;background:#e0e8df}.event-dot{width:9px;height:9px;border-radius:50%;background:#c0d0be;flex:none;margin-top:5px;position:relative;z-index:1}.inbound .event-dot{background:#0f6e5c}.event-content{flex:1;min-width:0}.event-meta{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;font-size:10px;color:#929d91}.event-meta strong{font-size:10px;font-weight:600;color:#627760;letter-spacing:.04em}.event-meta small{font-size:9px;color:#7f977c}.event-meta small.uncertain{color:#a86531}.event-content h5{font-size:14px;font-weight:600;margin:10px 0 5px}.event-address{font-size:10px;color:#929d91;margin:0 0 8px;overflow-wrap:anywhere}.event-summary,.event-preview{font-size:12px;line-height:1.8;color:#566954;margin:0 0 7px;white-space:pre-line}.message-original,.legacy-records pre{font:12px/1.8 var(--font-body);white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 0;padding:16px;background:#f8faf6;border:1px solid #e5eae3;border-radius:5px}.legacy-records{border-top:1px solid #e3e9e1;padding-top:14px;margin-top:10px;font-size:11px;color:#7c8b75}.legacy-records summary{cursor:pointer}.legacy-records article{margin-top:16px}.mail-composer{padding:22px;background:#fafcf8;border:1px solid #dce5d7;border-radius:6px;margin-bottom:24px}.mail-composer>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.mail-composer h4{font-size:16px;margin:0;font-weight:600}.mail-composer label{display:block;font-size:11px;color:#6c7b63;margin:14px 0 0}.mail-composer input,.mail-composer select,.mail-composer textarea,.offline-note select,.offline-note textarea{width:100%;box-sizing:border-box;border:1px solid #d7dfd0;background:#fff;border-radius:5px;padding:10px 12px;font:13px var(--font-body);color:#253820;margin-top:6px;min-height:40px}.mail-composer textarea{min-height:180px;resize:vertical;line-height:1.8}.mail-meta{display:grid;grid-template-columns:minmax(0,1fr) 130px;gap:16px}.ai-toolbar{display:flex;gap:12px;align-items:end}.ai-toolbar label{flex:1}.ai-button{min-height:40px;padding:9px 12px;border:1px solid #bdd0b4;background:#f0f6e9;color:#4e7542;flex:none}.mail-composer footer{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:20px}.mail-composer footer span,.configuration-note,.attachment-label{font-size:11px;color:#829277;line-height:1.7}.attachment-label{padding-top:10px}.offline-note{display:grid;grid-template-columns:120px 1fr;gap:12px;padding:16px;background:#f8faf5;margin-bottom:24px;border-radius:5px}.offline-note textarea{min-height:90px;margin:0}.offline-note select{margin:0;align-self:start}.offline-note button{grid-column:2;justify-self:end}.project-activity button:disabled{opacity:.45;cursor:default}.activity-notice{font-size:12px;padding:12px;color:#38743c;background:#f0f7e9}.activity-error{font-size:12px;line-height:1.7;color:#a05335;background:#fff7ed;padding:12px}@media(max-width:1100px){.activity-overview{grid-template-columns:1fr;gap:6px}.next-actions{padding:12px 0}}@media(max-width:640px){.activity-heading{align-items:start;gap:12px}.activity-heading h3{font-size:18px}.primary-button{padding:10px 12px;font-size:11px!important}.automatic-summary,.mail-composer{padding:17px}.activity-stream>header{align-items:start;flex-direction:column;gap:4px}.mail-meta{grid-template-columns:1fr;gap:0}.ai-toolbar{flex-direction:column;align-items:stretch}.ai-toolbar label{width:100%}.mail-composer footer{align-items:stretch;flex-direction:column}.offline-note{grid-template-columns:1fr}.offline-note button{grid-column:1}.message-event{gap:12px}}
</style>
